	Graphics_D3D11_ShaderCodePackage_GetInfo( &SizeBuf, &ShaderAddr, ( void ** )SCMD->MV1_MaterialType_PSAddress,			sizeof( SCMD->MV1_MaterialType_PSAddress			) / sizeof( void * ) ) ;

