// Direct3D9 ???V?F?[?_?[?\?[?X???R?Åg?p?C??????
extern int Graphics_D3D9_CompileShader( const char *FileName, const char *EntryPoint, const char *Profile, const char *SubProfile, const D_D3DXMACRO *MacroTable, D_ID3DXBuffer **ppShader )
{
	GRAPHICS_HARDWARE_DIRECT3D9_SHADERCODE *ShaderCode = &GraphicsHardDataDirect3D9.ShaderCode ;
	int Addr ;
	int Size ;
	void *DataImage ;
	void *Code ;
	DWORD CodeSize ;
	D_ID3DXBuffer *DestD3D9 = NULL ;
	D_ID3DXBuffer *ErrorD3D9 = NULL ;
	D_ID3DBlob *DestD3D11 = NULL ;
	D_ID3DBlob *ErrorD3D11 = NULL ;

	// ?V?F?[?_?[?\?[?X?t?@?C??????Åg?????
	if( DXA_GetFileInfo( &ShaderCode->Base.ShaderTxtDxa, DX_CHARCODEFORMAT_ASCII, FileName, &Addr, &Size ) != 0 )
	{
		return -1 ;
	}
	DataImage = ( BYTE * )DXA_GetFileImage( &ShaderCode->Base.ShaderTxtDxa ) + Addr ;

	// D3DX9 ?? DLL ??????????????????????????
	if( WinAPIData.Win32Func.D3DXCompileShaderFunc != NULL )
	{
		// D3DX9 ?? DLL ?????????Åˆ?? D3DX9 ?? DLL ???g?p????
		if( WinAPIData.Win32Func.D3DXCompileShaderFunc(
				( LPCTSTR )DataImage,
				( UINT )Size,
				MacroTable,
				ShaderCode->Base.ShaderCompilerIncludeClass,
				EntryPoint,
				Profile,
				0,
				&DestD3D9,
				&ErrorD3D9,
				NULL
			) == D_D3D_OK )
		{
			Code = DestD3D9->GetBufferPointer() ;
			CodeSize = DestD3D9->GetBufferSize() ;
		}
		else
		{
			// ??Åhs???????Åˆ???T?u?v???t?@?C????????
			if( SubProfile != NULL )
			{
				if( DestD3D9 != NULL )
				{
					DestD3D9->Release() ;
					DestD3D9 = NULL ;
				}

				if( ErrorD3D9 != NULL )
				{
					ErrorD3D9->Release() ;
					ErrorD3D9 = NULL ;
				}

				if( WinAPIData.Win32Func.D3DXCompileShaderFunc(
						( LPCTSTR )DataImage,
						( UINT )Size,
						MacroTable,
						ShaderCode->Base.ShaderCompilerIncludeClass,
						EntryPoint,
						SubProfile,
						0,
						&DestD3D9,
						&ErrorD3D9,
						NULL
					) == D_D3D_OK )
				{
					Code = DestD3D9->GetBufferPointer() ;
					CodeSize = DestD3D9->GetBufferSize() ;
				}
				else
				{
					DXST_LOGFILE_ADDA( "Direct3D 9 ShaderCode Compile Error\n" ) ;
					DXST_LOGFILE_ADDA( ( char * )ErrorD3D9->GetBufferPointer() ) ;
					DXST_LOGFILE_ADDA( "\n" ) ;
					goto ERR ;
				}
			}
			else
			{
				DXST_LOGFILE_ADDA( "Direct3D 9 ShaderCode Compile Error\n" ) ;
				DXST_LOGFILE_ADDA( ( char * )ErrorD3D9->GetBufferPointer() ) ;
				DXST_LOGFILE_ADDA( "\n" ) ;
				goto ERR ;
			}
		}

		*ppShader = DestD3D9 ;
	}
	else
	if( WinAPIData.Win32Func.D3DCompileFunc != NULL )
	{
		// D3DX9 ?? DLL ?????????Åˆ?? Direct3D 11 ?p?? DLL ???g?p????
		if( WinAPIData.Win32Func.D3DCompileFunc(
				( LPCTSTR )DataImage,
				( UINT )Size,
				NULL,
				MacroTable,
				ShaderCode->Base.ShaderCompilerIncludeClass,
				EntryPoint,
				Profile,
				0,
				0,
				&DestD3D11,
				&ErrorD3D11
			) == D_D3D_OK )
		{
			Code = DestD3D11->GetBufferPointer() ;
			CodeSize = ( DWORD )DestD3D11->GetBufferSize() ;
		}
		else
		{
			// ??Åhs???????Åˆ???T?u?v???t?@?C????????
			if( SubProfile != NULL )
			{
				if( DestD3D11 != NULL )
				{
					DestD3D11->Release() ;
					DestD3D11 = NULL ;
				}

				if( ErrorD3D11 != NULL )
				{
					ErrorD3D11->Release() ;
					ErrorD3D11 = NULL ;
				}

				if( WinAPIData.Win32Func.D3DCompileFunc(
						( LPCTSTR )DataImage,
						( UINT )Size,
						NULL,
						MacroTable,
						ShaderCode->Base.ShaderCompilerIncludeClass,
						EntryPoint,
						SubProfile,
						0,
						0,
						&DestD3D11,
						&ErrorD3D11
					) == D_D3D_OK )
				{
					Code = DestD3D11->GetBufferPointer() ;
					CodeSize = ( DWORD )DestD3D11->GetBufferSize() ;
				}
				else
				{
					DXST_LOGFILE_ADDA( "Direct3D 11 ShaderCode Compile Error\n" ) ;
					DXST_LOGFILE_ADDA( ( char * )ErrorD3D11->GetBufferPointer() ) ;
					DXST_LOGFILE_ADDA( "\n" ) ;
					goto ERR ;
				}
			}
			else
			{
				DXST_LOGFILE_ADDA( "Direct3D 11 ShaderCode Compile Error\n" ) ;
				DXST_LOGFILE_ADDA( ( char * )ErrorD3D11->GetBufferPointer() ) ;
				DXST_LOGFILE_ADDA( "\n" ) ;
				goto ERR ;
			}
		}

		*ppShader = ( D_ID3DXBuffer * )DestD3D11 ;
	}
	else
	{
		return -1 ;
	}

	if( ErrorD3D9 != NULL )
	{
		ErrorD3D9->Release() ;
		ErrorD3D9 = NULL ;
	}

	if( ErrorD3D11 != NULL )
	{
		ErrorD3D11->Release() ;
		ErrorD3D11 = NULL ;
	}

	return 0 ;

ERR :
	if( DestD3D9 != NULL )
	{
		DestD3D9->Release() ;
		DestD3D9 = NULL ;
	}

	if( ErrorD3D9 != NULL )
	{
		ErrorD3D9->Release() ;
		ErrorD3D9 = NULL ;
	}

	if( DestD3D11 != NULL )
	{
		DestD3D11->Release() ;
		DestD3D11 = NULL ;
	}

	if( ErrorD3D11 != NULL )
	{
		ErrorD3D11->Release() ;
		ErrorD3D11 = NULL ;
	}

	return -1 ;
}

// Direct3D9 ???V?F?[?_?[?\?[?X???R?Åg?p?C??????Åf?Åg_?V?F?[?_?[??????????
extern int Graphics_D3D9_CompileVertexShader( const char *FileName, const char *EntryPoint, const D_D3DXMACRO *MacroTable, D_IDirect3DVertexShader9 **VertexShader, int ShaderModel3Only, int ShaderModel2Only )
{
	D_ID3DXBuffer *Code = NULL ;
	HRESULT hr ;

	// ?V?F?[?_?[?\?[?X???R?Åg?p?C??
	if( ShaderModel3Only )
	{
		if( Graphics_D3D9_CompileShader( FileName, EntryPoint, "vs_3_0", NULL, MacroTable, &Code ) < 0 )
		{
			return -1 ;
		}
	}
	else
	if( ShaderModel2Only )
	{
		if( Graphics_D3D9_CompileShader( FileName, EntryPoint, "vs_2_0", NULL, MacroTable, &Code ) < 0 )
		{
			return -1 ;
		}
	}
	else
	{
		if( Graphics_D3D9_CompileShader( FileName, EntryPoint, "vs_2_0", "vs_3_0", MacroTable, &Code ) < 0 )
		{
			return -1 ;
		}
	}

	// ?V?F?[?_?[?o?C?i??????Åf?Åg_?V?F?[?_?[??????
	hr = Direct3DDevice9_CreateVertexShader( ( DWORD * )Code->GetBufferPointer(), VertexShader ) ;

	// ?V?F?[?_?[?o?C?i???????n??
	Code->Release() ;

	// ????Åfl??????
	return hr != D_D3D_OK ? -1 : 0 ;
}

