static int CreateD3D9BaseNoneTexPixelshader( int EffectType, int AlphaCh )
{
	D_D3DXMACRO Macro[ 4 ] ;
	int MacroNum = 0 ;

	// ?????????????????Åˆ??ÅÒ?????????
	if( GD3D9.Device.Shader.Base.BaseNoneTexPixelShader[ EffectType ][ AlphaCh ] != NULL )
	{
		return 0 ;
	}

	if( g_ShaderMacro_RenderBlendTypeName[ EffectType ] != NULL )
	{
		Macro[ MacroNum ].Name = g_ShaderMacro_RenderBlendTypeName[ EffectType ] ;
		Macro[ MacroNum ].Definition = "" ;
		MacroNum ++ ;
	}

	if( EffectType >= 4 )
	{
		Macro[ MacroNum ].Name = "PRE_MUL_ALPHA" ;
		Macro[ MacroNum ].Definition = "" ;
		MacroNum ++ ;
	}

	if( AlphaCh )
	{
		Macro[ MacroNum ].Name = "ALPHA_CH_DRAW" ;
		Macro[ MacroNum ].Definition = "" ;
		MacroNum ++ ;
	}

	Macro[ MacroNum ].Name = NULL ;
	Macro[ MacroNum ].Definition = NULL ;
	MacroNum ++ ;

	return Graphics_D3D9_CompilePixelShader( "Base.fx", "ps_notex_normal", Macro, &GD3D9.Device.Shader.Base.BaseNoneTexPixelShader[ EffectType ][ AlphaCh ] ) ;
}

