// ???f???`ÅÒ??p?s?N?Z??ÅfP???ÅÒ?C?e?B?Åg?O?^?C?v???s?N?Z???V?F?[?_?[???R?Åg?p?C?????s??
static int CreateD3D9Base3DPixelLightingNormalPixelShader( int ShadowMap, const int *LightMode, int Specular, int RenderBlendType )
{
	D_D3DXMACRO Macro[ 20 ] ;
	int MacroNum = 0 ;
	int i ;
	int LightIndex84 = GD3D9.ShaderCode.Base.LightIndexList84[ LightMode[ 0 ] ][ LightMode[ 1 ] ][ LightMode[ 2 ] ][ LightMode[ 3 ] ][ LightMode[ 4 ] ][ LightMode[ 5 ] ] ;

	// ?????????????????Åˆ??ÅÒ?????????
	if( GD3D9.Device.Shader.Base3D.Base3D_PixelLighting_Normal_PS[ ShadowMap ][ LightIndex84 ][ Specular ][ RenderBlendType ] != NULL )
	{
		return 0 ;
	}

	if( ShadowMap != 0 )
	{
		Macro[ MacroNum ].Name = "SHADOWMAP" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	if( Specular != 1 )
	{
		Macro[ MacroNum ].Name = "USE_SPE" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	Macro[ MacroNum ].Name = "LG_USE" ;
	Macro[ MacroNum ].Definition = "1" ;
	MacroNum ++ ;

	for( i = 0 ; i < 6 ; i ++ )
	{
		if( LightMode[ i ] == 0 )
		{
			continue ;
		}

		Macro[ MacroNum ].Name = g_ShaderMacro_LG_Use[ i ] ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;

		Macro[ MacroNum ].Name = g_ShaderMacro_LG_Type[ i ][ LightMode[ i ] ] ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	if( RenderBlendType >= 4 )
	{
		Macro[ MacroNum ].Name = "PRE_MUL_ALPHA" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	if( g_ShaderMacro_RenderBlendTypeName[ RenderBlendType ] != NULL )
	{
		Macro[ MacroNum ].Name = g_ShaderMacro_RenderBlendTypeName[ RenderBlendType ] ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	Macro[ MacroNum ].Name = NULL ;
	Macro[ MacroNum ].Definition = NULL ;
	MacroNum ++ ;

	return Graphics_D3D9_CompilePixelShader( "Base_3D_PixelLighting_PS.fx", "main", Macro, &GD3D9.Device.Shader.Base3D.Base3D_PixelLighting_Normal_PS[ ShadowMap ][ LightIndex84 ][ Specular ][ RenderBlendType ], TRUE ) ;
}

