	GRAPHICS_HARDWARE_DIRECT3D9_SHADER_MODEL     *SM     = &Shader->Model ;
	D_D3DXMACRO Macro[ 6 ] ;
	int MacroNum = 0 ;
	int ShadowMap ;
	int SkinMesh ;
	int BumpMap ;
	int FogType ;

	// ?????????????????Åˆ??ÅÒ?????????
	if( ( ( D_IDirect3DVertexShader9 ** )SM->MV1_PixelLighting_VS )[ VertexShaderIndex_PL ] != NULL )
	{
		return 0 ;
	}

	ShadowMap = D3D9_PIXELLIGHTING_VERTEXSHADER_GET_SHADOWMAP( VertexShaderIndex_PL ) ;
	SkinMesh  = D3D9_PIXELLIGHTING_VERTEXSHADER_GET_SKINMESH( VertexShaderIndex_PL ) ;
	BumpMap   = D3D9_PIXELLIGHTING_VERTEXSHADER_GET_BUMPMAP( VertexShaderIndex_PL ) ;
