	MacroNum ++ ;

	return Graphics_D3D9_CompileVertexShader( "MV1Default_PixelLighting_VS.fx", "main", Macro, &( ( D_IDirect3DVertexShader9 ** )SM->MV1_PixelLighting_VS )[ VertexShaderIndex_PL ], TRUE ) ;
