// ???f???`ÅÒ??p???ÅÒ?C?e?B?Åg?O????Åf?Åg_?V?F?[?_?[???R?Åg?p?C?????s??
static int CreateD3D9MV1VertexLightingVertexShader( int VertexShaderIndex )
{
	GRAPHICS_HARDDATA_DIRECT3D9_DEVICE           *Device = &GraphicsHardDataDirect3D9.Device ;
	GRAPHICS_HARDWARE_DIRECT3D9_SHADER           *Shader = &Device->Shader ;
	GRAPHICS_HARDWARE_DIRECT3D9_SHADER_MODEL     *SM     = &Shader->Model ;
	const BYTE *LightMode ;
	int i ;
	D_D3DXMACRO Macro[ 20 ] ;
	int MacroNum = 0 ;

	int VS_MeshType    = D3D9_VERTEXSHADER_GET_MESHTYPE(    VertexShaderIndex ) ;
	int VS_FogMode     = D3D9_VERTEXSHADER_GET_FOGMODE(     VertexShaderIndex ) ;

	int VS_LightIndex  = D3D9_VERTEXSHADER_GET_LIGHTINDEX(  VertexShaderIndex ) ;

	int VS_ShaderModel = D3D9_VERTEXSHADER_GET_SHADERMODEL( VertexShaderIndex ) ;
	int VS_ShadowMap   = D3D9_VERTEXSHADER_GET_SHADOWMAP(   VertexShaderIndex ) ;
	int VS_BumpMap     = D3D9_VERTEXSHADER_GET_BUMPMAP(     VertexShaderIndex ) ;
	int VS_Specular    = D3D9_VERTEXSHADER_GET_SPECULAR(    VertexShaderIndex ) ;

	LightMode = GD3D9.ShaderCode.Base.LightIndex20LightMode[ VS_LightIndex ] ;

	// ?????????????????Åˆ??ÅÒ?????????
	if( SM->MV1_VertexLighting_VS[ VS_ShaderModel ][ VS_ShadowMap ][ VS_MeshType ][ VS_BumpMap ][ VS_FogMode ][ VS_LightIndex ][ VS_Specular ] != NULL )
	{
		return 0 ;
	}

	if( VS_MeshType > 0 )
	{
		Macro[ MacroNum ].Name = "SKINMESH" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;

		if( VS_MeshType == 2 )
		{
			Macro[ MacroNum ].Name = "BONE8" ;
			Macro[ MacroNum ].Definition = "1" ;
			MacroNum ++ ;
		}
	}

	if( g_ShaderMacro_FogTypeName[ VS_FogMode ] != NULL )
	{
		Macro[ MacroNum ].Name = g_ShaderMacro_FogTypeName[ VS_FogMode ] ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	Macro[ MacroNum ].Name = "PHONG" ;
	Macro[ MacroNum ].Definition = "1" ;
	MacroNum ++ ;

	if( VS_ShadowMap != 0 )
	{
		Macro[ MacroNum ].Name = "SHADOWMAP" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	if( VS_BumpMap != 0 )
	{
		Macro[ MacroNum ].Name = "BUMPMAP" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	if( VS_Specular != 0 )
	{
		Macro[ MacroNum ].Name = "USE_SPE" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	Macro[ MacroNum ].Name = "LG_USE" ;
	Macro[ MacroNum ].Definition = "1" ;
	MacroNum ++ ;

	for( i = 0 ; i < 3 ; i ++ )
	{
		if( LightMode[ i ] == 0 )
		{
			continue ;
		}

		Macro[ MacroNum ].Name = g_ShaderMacro_LG_Use[ i ] ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;

		Macro[ MacroNum ].Name = g_ShaderMacro_LG_Type[ i ][ LightMode[ i ] ] ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	if( VS_ShaderModel != 0 )
	{
		Macro[ MacroNum ].Name = "SM_3" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	Macro[ MacroNum ].Name = NULL ;
	Macro[ MacroNum ].Definition = NULL ;
	MacroNum ++ ;

	if( VS_ShaderModel != 0 )
	{
		return Graphics_D3D9_CompileVertexShader( "MV1Default_VertexLighting_VS.fx", "main", Macro, &SM->MV1_VertexLighting_VS[ VS_ShaderModel ][ VS_ShadowMap ][ VS_MeshType ][ VS_BumpMap ][ VS_FogMode ][ VS_LightIndex ][ VS_Specular ], TRUE ) ;
	}
	else
	{
		int Result ;

		Result = Graphics_D3D9_CompileVertexShader( "MV1Default_VertexLighting_VS.fx", "main", Macro, &SM->MV1_VertexLighting_VS[ VS_ShaderModel ][ VS_ShadowMap ][ VS_MeshType ][ VS_BumpMap ][ VS_FogMode ][ VS_LightIndex ][ VS_Specular ], FALSE, TRUE ) ;

		if( Result < 0 )
		{
			MacroNum -- ;

			Macro[ MacroNum ].Name = "SM_3" ;
			Macro[ MacroNum ].Definition = "1" ;
			MacroNum ++ ;

			Macro[ MacroNum ].Name = NULL ;
			Macro[ MacroNum ].Definition = NULL ;
			MacroNum ++ ;

			return Graphics_D3D9_CompileVertexShader( "MV1Default_VertexLighting_VS.fx", "main", Macro, &SM->MV1_VertexLighting_VS[ VS_ShaderModel ][ VS_ShadowMap ][ VS_MeshType ][ VS_BumpMap ][ VS_FogMode ][ VS_LightIndex ][ VS_Specular ], TRUE ) ;
		}
		else
		{
			return Result ;
		}
	}
}

