// ???f???`ÅÒ??p???}?e???A???vÅef?`ÅÒ??p?s?N?Z???V?F?[?_?[???R?Åg?p?C?????s??
static int CreateD3D9MV1MaterialTypePixelShader( int MaterialType )
{
	GRAPHICS_HARDDATA_DIRECT3D9_DEVICE           *Device = &GraphicsHardDataDirect3D9.Device ;
	GRAPHICS_HARDWARE_DIRECT3D9_SHADER           *Shader = &Device->Shader ;
	GRAPHICS_HARDWARE_DIRECT3D9_SHADER_MODEL     *SM     = &Shader->Model ;
	D_D3DXMACRO Macro[ 6 ] ;
	int MacroNum = 0 ;

	// ?????????????????Åˆ??ÅÒ?????????
	if( SM->MV1_MaterialType_PS[ MaterialType ] != NULL )
	{
		return 0 ;
	}

	Macro[ MacroNum ].Name = "MAT_TYPE" ;
	Macro[ MacroNum ].Definition = g_ShaderMacro_NumTable[ MaterialType ] ;
	MacroNum ++ ;

	if( MaterialType >= DX_MATERIAL_TYPE_MAT_SPEC_LUMINANCE_UNORM && MaterialType <= DX_MATERIAL_TYPE_MAT_SPEC_LUMINANCE_CMP_GREATEREQUAL )
	{
		Macro[ MacroNum ].Name = "MAT_PARAM_SPEC_LUMINANCE" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}
	else
	if( MaterialType >= DX_MATERIAL_TYPE_MAT_SPEC_POWER_UNORM && MaterialType <= DX_MATERIAL_TYPE_MAT_SPEC_POWER_CMP_GREATEREQUAL )
	{
		Macro[ MacroNum ].Name = "MAT_PARAM_SPEC_POWER" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}
	else
	{
		Macro[ MacroNum ].Name = "MAT_PARAM_SPEC_POWER" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	switch( MaterialType )
	{
	default :
	case DX_MATERIAL_TYPE_MAT_SPEC_LUMINANCE_UNORM :
	case DX_MATERIAL_TYPE_MAT_SPEC_POWER_UNORM :
		Macro[ MacroNum ].Name = "MAT_CALC_UNORM" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
		break ;

	case DX_MATERIAL_TYPE_MAT_SPEC_LUMINANCE_CLIP_UNORM :
	case DX_MATERIAL_TYPE_MAT_SPEC_POWER_CLIP_UNORM :
		Macro[ MacroNum ].Name = "MAT_CALC_CLIP_UNORM" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
		break ;

	case DX_MATERIAL_TYPE_MAT_SPEC_LUMINANCE_CMP_GREATEREQUAL :
	case DX_MATERIAL_TYPE_MAT_SPEC_POWER_CMP_GREATEREQUAL :
		Macro[ MacroNum ].Name = "MAT_CALC_CMP_GREATEREQUAL" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
		break ;
	}

	Macro[ MacroNum ].Name = NULL ;
	Macro[ MacroNum ].Definition = NULL ;
	MacroNum ++ ;

	return Graphics_D3D9_CompilePixelShader( "MV1Default_VertexLighting_PS.fx", "main", Macro, &SM->MV1_MaterialType_PS[ MaterialType ], FALSE, TRUE ) ;
}

