	Macro[ MacroNum ].Name = "SUBTEXTUREMODE" ;
	Macro[ MacroNum ].Definition = g_ShaderMacro_NumTable[ MultiTexBlendMode ] ;
	MacroNum ++ ;

	Macro[ MacroNum ].Name = NULL ;
