// ???f???`ÅÒ??p???ÅÒ?C?e?B?Åg?O?????s?N?Z???V?F?[?_?[???R?Åg?p?C?????s??
static int CreateD3D9MV1VertexLightingNormalPixelShader( int PixelShaderIndex )
{
	GRAPHICS_HARDDATA_DIRECT3D9_DEVICE           *Device = &GraphicsHardDataDirect3D9.Device ;
	GRAPHICS_HARDWARE_DIRECT3D9_SHADER           *Shader = &Device->Shader ;
	GRAPHICS_HARDWARE_DIRECT3D9_SHADER_MODEL     *SM     = &Shader->Model ;
	const BYTE *LightMode ;
	int i ;
	D_D3DXMACRO Macro[ 20 ] ;
	int MacroNum = 0 ;

	int PS_ShaderModel       = D3D9_PIXELSHADER_GET_SHADERMODEL(  PixelShaderIndex ) ;
	int PS_ShadowMap         = D3D9_PIXELSHADER_GET_SHADOWMAP(    PixelShaderIndex ) ;
	int PS_SpecularMap       = D3D9_PIXELSHADER_GET_SPECULARMAP(  PixelShaderIndex ) ;
	int PS_BumpMap           = D3D9_PIXELSHADER_GET_BUMPMAP(      PixelShaderIndex ) ;
	int PS_LightIndex        = D3D9_PIXELSHADER_GET_LIGHTINDEX(   PixelShaderIndex ) ;
	int PS_Specular          = D3D9_PIXELSHADER_GET_SPECULAR(     PixelShaderIndex ) ;

	int PS_MultiTexBlendMode = D3D9_PIXELSHADER_GET_MULTITEX(     PixelShaderIndex ) ;

	LightMode = GD3D9.ShaderCode.Base.LightIndex10LightMode[ PS_LightIndex ] ;

	// ?????????????????Åˆ??ÅÒ?????????
	if( SM->MV1_VertexLighting_Normal_PS[ PS_ShaderModel ][ PS_ShadowMap ][ PS_MultiTexBlendMode ][ PS_SpecularMap ][ PS_BumpMap ][ PS_LightIndex ][ PS_Specular ] != NULL )
	{
		return 0 ;
	}

	if( PS_ShadowMap != 0 )
	{
		Macro[ MacroNum ].Name = "SHADOWMAP" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	Macro[ MacroNum ].Name = "SUBTEXTUREMODE" ;
	Macro[ MacroNum ].Definition = g_ShaderMacro_NumTable[ PS_MultiTexBlendMode ] ;
	MacroNum ++ ;

	if( PS_SpecularMap != 0 )
	{
		Macro[ MacroNum ].Name = "USE_SPETEX" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	if( PS_BumpMap != 0 )
	{
		Macro[ MacroNum ].Name = "BUMPMAP" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	Macro[ MacroNum ].Name = "PHONG" ;
	Macro[ MacroNum ].Definition = "1" ;
	MacroNum ++ ;

	if( PS_Specular != 0 )
	{
		Macro[ MacroNum ].Name = "USE_SPE" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	Macro[ MacroNum ].Name = "LG_USE" ;
	Macro[ MacroNum ].Definition = "1" ;
	MacroNum ++ ;

	for( i = 0 ; i < 3 ; i ++ )
	{
		if( LightMode[ i ] == 0 )
		{
			continue ;
		}

		Macro[ MacroNum ].Name = g_ShaderMacro_LG_Use[ i ] ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;

		if( LightMode[ i ] == DX_LIGHTTYPE_D3DLIGHT_DIRECTIONAL )
		{
			Macro[ MacroNum ].Name = g_ShaderMacro_LG_Type[ i ][ LightMode[ i ] ] ;
			Macro[ MacroNum ].Definition = "1" ;
			MacroNum ++ ;
		}
	}

	if( PS_ShaderModel != 0 )
	{
		Macro[ MacroNum ].Name = "SM_3" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	Macro[ MacroNum ].Name = NULL ;
	Macro[ MacroNum ].Definition = NULL ;
	MacroNum ++ ;

	if( PS_ShaderModel != 0 )
	{
		return Graphics_D3D9_CompilePixelShader( "MV1Default_VertexLighting_PS.fx", "main", Macro, &SM->MV1_VertexLighting_Normal_PS[ PS_ShaderModel ][ PS_ShadowMap ][ PS_MultiTexBlendMode ][ PS_SpecularMap ][ PS_BumpMap ][ PS_LightIndex ][ PS_Specular ], TRUE ) ;
	}
	else
	{
		int Result ;

		Result = Graphics_D3D9_CompilePixelShader( "MV1Default_VertexLighting_PS.fx", "main", Macro, &SM->MV1_VertexLighting_Normal_PS[ PS_ShaderModel ][ PS_ShadowMap ][ PS_MultiTexBlendMode ][ PS_SpecularMap ][ PS_BumpMap ][ PS_LightIndex ][ PS_Specular ], FALSE, TRUE ) ;

		if( Result < 0 )
		{
			MacroNum -- ;

			Macro[ MacroNum ].Name = "SM_3" ;
			Macro[ MacroNum ].Definition = "1" ;
			MacroNum ++ ;

			Macro[ MacroNum ].Name = NULL ;
			Macro[ MacroNum ].Definition = NULL ;
			MacroNum ++ ;

			return Graphics_D3D9_CompilePixelShader( "MV1Default_VertexLighting_PS.fx", "main", Macro, &SM->MV1_VertexLighting_Normal_PS[ PS_ShaderModel ][ PS_ShadowMap ][ PS_MultiTexBlendMode ][ PS_SpecularMap ][ PS_BumpMap ][ PS_LightIndex ][ PS_Specular ], TRUE ) ;
		}
		else
		{
			return Result ;
		}
	}
}

// ???f???`ÅÒ??p???V???h?E?}?b?v?????g?D?[?Åg???Åg?_???Åg?O?p?s?N?Z???V?F?[?_?[???R?Åg?p?C?????s??
static int CreateD3D9MV1ShadowMapToonPixelShader( int ToonType, int ToonSphereOP, int ToonDiffuseBlendOP )
{
	GRAPHICS_HARDDATA_DIRECT3D9_DEVICE           *Device = &GraphicsHardDataDirect3D9.Device ;
	GRAPHICS_HARDWARE_DIRECT3D9_SHADER           *Shader = &Device->Shader ;
	GRAPHICS_HARDWARE_DIRECT3D9_SHADER_MODEL     *SM     = &Shader->Model ;
	D_D3DXMACRO Macro[ 6 ] ;
	int MacroNum = 0 ;

	// ?????????????????Åˆ??ÅÒ?????????
	if( SM->MV1_ShadowMap_Toon_PS[ ToonType ][ ToonSphereOP ][ ToonDiffuseBlendOP ] != NULL )
	{
		return 0 ;
	}

	Macro[ MacroNum ].Name = "SHADOWMAP_DRAW" ;
	Macro[ MacroNum ].Definition = "1" ;
	MacroNum ++ ;

	Macro[ MacroNum ].Name = "TOON" ;
	Macro[ MacroNum ].Definition = g_ShaderMacro_NumTable[ ToonType + 1 ] ;
	MacroNum ++ ;

	Macro[ MacroNum ].Name = "PHONG" ;
	Macro[ MacroNum ].Definition = "1" ;
	MacroNum ++ ;

	if( ToonSphereOP != 0 )
	{
		if( ToonSphereOP == 1 )
		{
			Macro[ MacroNum ].Name = "TOON_SPHEREOP_MUL" ;
			Macro[ MacroNum ].Definition = "1" ;
			MacroNum ++ ;
		}
		else
		if( ToonSphereOP == 2 )
		{
			Macro[ MacroNum ].Name = "TOON_SPHEREOP_ADD" ;
			Macro[ MacroNum ].Definition = "1" ;
			MacroNum ++ ;
		}
	}
	if( ToonType == 0 )
	{
		if( ToonDiffuseBlendOP == 0 )
		{
			Macro[ MacroNum ].Name = "TOON_DIFOP_TRANS" ;
			Macro[ MacroNum ].Definition = "1" ;
			MacroNum ++ ;
		}
		else
		{
			Macro[ MacroNum ].Name = "TOON_DIFOP_MUL" ;
			Macro[ MacroNum ].Definition = "1" ;
			MacroNum ++ ;
		}
	}

	Macro[ MacroNum ].Name = NULL ;
	Macro[ MacroNum ].Definition = NULL ;
	MacroNum ++ ;

	return Graphics_D3D9_CompilePixelShader( "MV1Default_VertexLighting_PS.fx", "main", Macro, &SM->MV1_ShadowMap_Toon_PS[ ToonType ][ ToonSphereOP ][ ToonDiffuseBlendOP ], FALSE, TRUE ) ;
}

