		return Graphics_D3D9_DrawModiGraphF( (float)x1 - 0.5f, (float)y1 - 0.5f, (float)x2 - 0.5f, (float)y2 - 0.5f, (float)x3 - 0.5f, (float)y3 - 0.5f, (float)x4 - 0.5f, (float)y4 - 0.5f, Image, BlendImage, TransFlag, SimpleDrawFlag ) ;

