		// ????ÅgI???????????T?[?t?F?X??ÅÒ???
		// Direct3D9_ObjectRelease( GD3D9.Device.Screen.DrawScreenBufferLockSMSurface ) ;
		Graphics_D3D9_ReleaseSysMemSurface( GD3D9.Device.Screen.DrawScreenBufferLockSMSurfaceIndex, FALSE ) ;

